#include <bits/stdc++.h>
using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

    vector<string> grid(n);
    for (auto& row : grid) cin >> row;

    int sum = 0;
    const int di[] = {0, 0, -1, 1};
    const int dj[] = {-1, 1, 0, 0};

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            if (grid[i][j] != 'W') continue;

            for (int d = 0; d < 4; ++d) {
                int ni = i + di[d];
                int nj = j + dj[d];

                if (ni >= 0 && ni < n && nj >= 0 && nj < m &&
                    grid[ni][nj] == 'P') {
                    ++sum;
                    grid[ni][nj] = '.';
                    break;
                }
            }
        }
    }

    cout << sum;
    return 0;
}

